<script setup lang="ts">
import type { Report } from '~/types/lapormas'
definePageMeta({ layout: 'app', middleware: 'auth', title: 'Rekapitulasi' })
const { state, createRecap } = useLaporMas()
const period = ref(new Date().toISOString().slice(0, 7))
const title = ref('Rekapitulasi Laporan ' + new Intl.DateTimeFormat('id-ID', { month:'long', year:'numeric' }).format(new Date()))
const summary = ref('Rangkuman laporan warga berdasarkan kategori dan status penanganan pada periode ini.')
const success = ref('')
const monthReports = computed(() => state.value.reports.filter(r => r.createdAt.slice(0,7) === period.value && !['Menunggu verifikasi', 'Ditolak'].includes(r.status)))
const published = computed(() => [...state.value.recaps].sort((a,b) => b.publishedAt.localeCompare(a.publishedAt)))
function publish() { if (createRecap({ title: title.value, period: period.value, summary: summary.value })) success.value = 'Rekapitulasi berhasil diterbitkan untuk pengguna.' }
function exportCsv() { const rows = [['Nomor tiket','Judul','Kategori','Lokasi','Tanggal','Status','Prioritas'], ...monthReports.value.map(r => [r.ticket, r.title, r.category, r.location, new Date(r.createdAt).toLocaleDateString('id-ID'), r.status, r.priority])]; downloadCsv(rows, `lapormas-laporan-${period.value}.csv`) }
function downloadCsv(rows: string[][], fileName: string) { const csv = '\uFEFF' + rows.map(row => row.map(value => `"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n'); const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = fileName; a.click(); URL.revokeObjectURL(url) }
</script>
<template><div class="page-stack"><div class="page-title-row"><div><div class="eyebrow">LAPORAN BERKALA · F008 / F009</div><h1>Rekapitulasi laporan</h1><p>Susun ringkasan bulanan dan terbitkan untuk Ketua RT serta pengguna.</p></div></div><div v-if="success" class="success-banner"><span>✓</span>{{ success }}<button @click="success = ''">×</button></div><div class="recap-layout"><section class="panel recap-builder"><div class="eyebrow">01 · SUSUN REKAP</div><h3>Terbitkan rekapitulasi baru</h3><p class="panel-description">Rekap menghitung laporan terverifikasi, ditangani, dan selesai pada bulan yang dipilih.</p><form class="form-stack" @submit.prevent="publish"><label class="field-label">Periode rekap <input v-model="period" type="month" class="text-input" required/></label><label class="field-label">Judul rekap <input v-model="title" class="text-input" required maxlength="100"/></label><label class="field-label">Ringkasan <textarea v-model="summary" class="text-input textarea" rows="3" required/></label><div class="recap-preview"><div><small>LAPORAN TERPILIH</small><strong>{{ monthReports.length }}</strong></div><div><small>SELESAI</small><strong>{{ monthReports.filter(r => r.status === 'Selesai').length }}</strong></div><div><small>DALAM PROSES</small><strong>{{ monthReports.filter(r => r.status === 'Ditangani' || r.status === 'Terverifikasi').length }}</strong></div></div><button class="btn btn-primary btn-full">Terbitkan rekapitulasi ↗</button><button type="button" class="btn btn-outline btn-full" @click="exportCsv">Unduh data periode ini (.csv) ↓</button></form></section><section class="panel recap-history"><div class="panel-heading"><div><div class="eyebrow">02 · ARSIP PUBLIKASI</div><h3>Rekap yang diterbitkan</h3><p>Dokumen ringkasan yang tersedia untuk pengurus RT.</p></div><span class="count-pill">{{ published.length }} file</span></div><div v-if="published.length" class="recap-list"><div v-for="recap in published" :key="recap.id" class="recap-item"><span class="recap-file-icon">▦</span><div class="recap-item-copy"><b>{{ recap.title }}</b><small>{{ recap.period }} · Diterbitkan {{ new Date(recap.publishedAt).toLocaleDateString('id-ID') }}</small><p>{{ recap.summary }}</p><div class="recap-mini-stats"><span>{{ recap.totalReports }} laporan</span><span>{{ recap.completedReports }} selesai</span></div></div><span class="published-label">Terbit</span></div></div><EmptyState v-else title="Belum ada rekap" description="Terbitkan rekap pertama untuk mulai membangun arsip laporan."/></section></div></div></template>
